-- 06-judgment.sql
--
-- EXTRACTED VERBATIM from artifacts/v1/gaos-arcadedb-model.html, which is the
-- source of truth for this schema. Do not edit this file to change the model:
-- change the document, then re-extract. A deviation that lives only here is a
-- schema nobody reviewing the model document would ever see.
--
-- Applied in filename order by deploy/schema/apply.sh. Every statement carries
-- IF NOT EXISTS, so applying twice is a no-op rather than an error.

-- Dimension scores are stored separately from the weighted total so the
-- weights can change later without losing the evidence they were applied to.
-- safety is the veto dimension from architecture §06.
CREATE VERTEX TYPE Review IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Review.verdict      STRING  (mandatory true, notnull true,
                 regexp 'ACCEPT|ACCEPT_WITH_CLEANUP|ITERATE|ESCALATE|STOP|SAFETY_VETO');
CREATE PROPERTY Review.finalScore   INTEGER (mandatory true, notnull true, min 0, max 100);
CREATE PROPERTY Review.correctness  INTEGER (min 0, max 100);
CREATE PROPERTY Review.completeness INTEGER (min 0, max 100);
CREATE PROPERTY Review.safety       INTEGER (min 0, max 100);
CREATE PROPERTY Review.quality      INTEGER (min 0, max 100);
CREATE PROPERTY Review.efficiency   INTEGER (min 0, max 100);
CREATE PROPERTY Review.weights      MAP;      -- the weights actually used
CREATE PROPERTY Review.findings     LIST;
CREATE PROPERTY Review.reasonCode   STRING;   -- mandatory on every STOP
CREATE PROPERTY Review.reviewedAt   DATETIME (mandatory true);

CREATE VERTEX TYPE Approval IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Approval.decision  STRING (mandatory true, notnull true,
                 regexp 'REQUESTED|GRANTED|REJECTED|EXPIRED');
CREATE PROPERTY Approval.decidedBy STRING;
CREATE PROPERTY Approval.decidedAt DATETIME;
CREATE PROPERTY Approval.reason    STRING;

CREATE VERTEX TYPE Decision IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Decision.key        STRING (mandatory true, notnull true);   -- ADR-014
CREATE PROPERTY Decision.title      STRING (mandatory true, notnull true);
CREATE PROPERTY Decision.statement  STRING;
CREATE PROPERTY Decision.confidence FLOAT  (default 0.5, min 0, max 1);
CREATE PROPERTY Decision.status     STRING (default 'ACCEPTED',
                 regexp 'PROPOSED|ACCEPTED|SUPERSEDED|REJECTED');
CREATE PROPERTY Decision.supersedes STRING;

-- embedding is optional. If you enable it, index it with LSM_VECTOR so
-- "have we solved something like this before?" is a similarity search
-- rather than a tag match.
CREATE VERTEX TYPE Knowledge IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Knowledge.title      STRING (mandatory true, notnull true);
CREATE PROPERTY Knowledge.summary    STRING (mandatory true, notnull true);
CREATE PROPERTY Knowledge.kind       STRING (regexp 'lesson|failure_pattern|pattern|routing');
CREATE PROPERTY Knowledge.tags       LIST;
CREATE PROPERTY Knowledge.confidence FLOAT   (default 0.5, min 0, max 1);
CREATE PROPERTY Knowledge.reuseCount INTEGER (default 0, min 0);
CREATE PROPERTY Knowledge.embedding  ARRAY_OF_FLOATS;

CREATE VERTEX TYPE Meeting IF NOT EXISTS EXTENDS GaosVertex;
CREATE PROPERTY Meeting.reason     STRING (mandatory true, notnull true);
CREATE PROPERTY Meeting.agenda     LIST;
CREATE PROPERTY Meeting.state      STRING (default 'PREPARING',
                 regexp 'PREPARING|GATHERING|DISCUSSION|DECISION|CLOSED');
CREATE PROPERTY Meeting.confidence FLOAT  (default 0, min 0, max 1);
CREATE PROPERTY Meeting.startedAt  DATETIME;
CREATE PROPERTY Meeting.closedAt   DATETIME;
